const out = $input.first().json.output;
const s = $('Calculate Metrics').first().json.stats;
const now = $now;

const lines = (arr, fn) => (arr || []).map(x => '• ' + fn(x)).join('\n');

return [{
  json: {
    'Report ID': `RPT-${now.toFormat('yyyyMMdd-HHmm')}`,
    'Date': now.toFormat('yyyy-MM-dd'),
    'Data Type': 'Simulated',
    'Videos Analyzed': s.overall.videos_analyzed,
    'Total Views': s.overall.total_views,
    'Avg Engagement Rate': s.overall.avg_engagement_rate + '%',
    'Overall Summary': out.overall_summary + ' ' + (out.data_note || ''),
    'Higher Engagement Topics': lines(out.higher_engagement_topics, t => `${t.topic}: ${t.evidence}`),
    'Lower Engagement Topics': lines(out.lower_engagement_topics, t => `${t.topic}: ${t.evidence}`),
    'Video Summaries': lines(out.video_summaries, v => `${v.video_id}: ${v.summary}`),
    'Suggested Topics': lines(out.suggested_topics, t => `${t.title} (${t.reason}; ${t.evidence})`),
    'Improvements': lines(out.improvements, i => `${i.area}: ${i.suggestion} (${i.evidence})`),
    'Status': 'Needs Review'
  }
}];
